import {
  Color,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  uniform,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, DirectionalLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const hexToVec3 = (hex) => {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  };

  const inkColor = hexToVec3(colors.ink);
  const surfaceColor = hexToVec3(colors.surface);
  const accentColor = hexToVec3(colors.accent);
  const paperColor = colors.paper;

  const group = new Group();
  group.name = 'features-card-2-label';

  // ---- Background panel: engineered gradient + subtle grain ----
  const panelW = 2.4;
  const panelH = 0.6;
  const panelGeo = new PlaneGeometry(panelW, panelH, 1, 1);
  const panelMat = new MeshPhysicalNodeMaterial();

  const uvNode = uv();
  const gradient = mix(surfaceColor, inkColor, uvNode.y);

  // deterministic grain (no time dependency — static composition)
  const grainSeed = uvNode.mul(vec2(1345.7, 6789.3));
  const grainRaw = grainSeed.dot(vec2(12.9898, 78.233)).sin().mul(43758.5453).fract();
  const grain = grainRaw.sub(0.5).mul(0.025);

  panelMat.colorNode = gradient.add(grain);
  panelMat.roughness = 0.58;
  panelMat.metalness = 0.42;
  panelMat.clearcoat = 0.18;
  panelMat.clearcoatRoughness = 0.4;
  panelMat.transparent = true;
  panelMat.opacity = 1.0;

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  group.add(panel);

  // ---- Accent underline (single brightest small element) ----
  const underlineGeo = new PlaneGeometry(0.42, 0.03, 1, 1);
  const underlineMat = new MeshBasicNodeMaterial();
  underlineMat.colorNode = accentColor;
  underlineMat.transparent = true;
  underlineMat.opacity = 0.95;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(-0.72, -0.18, 0.005);
  group.add(underline);

  // ---- Decorative orb texture (foreground accent, small) ----
  const orbGeo = new PlaneGeometry(0.34, 0.34, 1, 1);
  const orbMat = new MeshBasicNodeMaterial();
  orbMat.transparent = true;
  orbMat.opacity = 0.0; // fade in once loaded
  const orbMesh = new Mesh(orbGeo, orbMat);
  orbMesh.position.set(0.92, 0.02, 0.01);
  group.add(orbMesh);

  let orbTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      orbTexture = tex;
      orbMat.colorNode = texture(tex);
      orbMat.needsUpdate = true;
      gsap.to(orbMat, { opacity: 0.85, duration: 0.5, ease: 'power2.out' });
    }).catch(() => {});
  }

  // ---- Rim light (node-local, machined-metal definition) ----
  const rim = new DirectionalLight(new Color(colors.paper), 0.55);
  rim.position.set(-1.2, 0.6, 1.4);
  group.add(rim);

  // ---- Text: headline "Features 2" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = headlineItem?.text ?? 'Features 2';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize,
    color: paperColor,
    align: 'left',
    maxWidthPx: 480,
  });
  headline.position.set(-0.98, 0.02, 0.008);
  group.add(headline);

  // ---- Scene placement (position/rotation applied by adapter; scale respected here) ----
  group.scale.set(1, 1, 1);

  // ---- Entrance motion: weighted, static composition (no idle loop) ----
  panelMat.opacity = 0;
  underlineMat.opacity = 0;
  headline.traverse((n) => {
    if (n.material) {
      n.material.transparent = true;
      n.material.opacity = 0;
    }
  });
  group.position.y -= 0.12;

  const tl = gsap.timeline();
  tl.to(panelMat, { opacity: 1, duration: 0.6, ease: 'power2.out' });
  tl.to(underlineMat, { opacity: 0.95, duration: 0.5, ease: 'power2.out' }, 0.1);
  tl.to(group.position, { y: group.position.y + 0.12, duration: 0.7, ease: 'power3.out' }, 0);
  headline.traverse((n) => {
    if (n.material) {
      tl.to(n.material, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.15);
    }
  });

  // ---- Handlers (none — static, non-interactive) ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    panelGeo.dispose();
    panelMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    orbGeo.dispose();
    orbMat.dispose();
    if (orbTexture && orbTexture.dispose) orbTexture.dispose();
    rim.dispose?.();
    headline.traverse((n) => {
      if (n.geometry) n.geometry.dispose();
      if (n.material) n.material.dispose();
    });
  };

  return group;
}
